Function valor <- PrecioDe(codigo As Integer)
  Define valor As Integer;
  Switch codigo Do
    1:
      valor <- 3;
    2:
      valor <- 5;
    3:
      valor <- 2;
    4:
      valor <- 1;
    Otherwise:
      valor <- 2;
  EndSwitch
EndFunction

Function importe <- Linea(precio As Integer, cantidad As Integer)
  Define importe As Integer;
  importe <- precio * cantidad;
EndFunction

Function monto <- ConDescuento(total As Integer)
  Define monto As Integer;
  monto <- total - total Div 10;
EndFunction

Algorithm Ticket
  Define codigo1, cantidad1, codigo2, cantidad2 As Integer;
  Read codigo1;
  Read cantidad1;
  Read codigo2;
  Read cantidad2;
  Write ConDescuento(Linea(PrecioDe(codigo1), cantidad1) + Linea(PrecioDe(codigo2), cantidad2));
EndAlgorithm
